-- ---------- 5. 当前客流快照（取 2026-10-22 11:00 的流量值，供用户端首页/地图展示）----------
UPDATE scenic_spot SET
  current_visitors = COALESCE((
    SELECT f.current_visitors FROM flow_record f
    WHERE f.spot_id = scenic_spot.spot_id AND f.is_deleted = 0
      AND f.record_time = '2026-10-22 11:00:00'), 0),
  cumulative_visitors = COALESCE((
    SELECT MAX(f.cumulative_visitors) FROM flow_record f
    WHERE f.spot_id = scenic_spot.spot_id AND f.is_deleted = 0
      AND date(f.record_time) = '2026-10-22'), 0),
  arrival_rate = COALESCE((
    SELECT f.arrival_rate FROM flow_record f
    WHERE f.spot_id = scenic_spot.spot_id AND f.is_deleted = 0
      AND f.record_time = '2026-10-22 11:00:00'), 0),
  departure_rate = COALESCE((
    SELECT f.departure_rate FROM flow_record f
    WHERE f.spot_id = scenic_spot.spot_id AND f.is_deleted = 0
      AND f.record_time = '2026-10-22 11:00:00'), 0),
  updated_at = datetime('now','localtime');

